{"command":"cat <<'EOF' > main.go
package main

import (
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strings"
)

var (
	configPath    = flag.String("config", "", "path to the configuration TOML file")
	formatterName = flag.String("formatter", "default", "formatter to be used for the output")
	maxOpenFiles  = flag.Int("max_open_files", 0, "maximum number of open files at the same time")
	setExitStatus = flag.Bool("set_exit_status", false, "set exit status to 1 if any issues are found")
	versionFlag   = flag.Bool("version", false, "get revive version")
)

type excludeFlags []string

func (i *excludeFlags) String() string {
	return fmt.Sprint(*i)
}

func (i *excludeFlags) Set(value string) error {
	*i = append(*i, value)
	return nil
}

var excludes excludeFlags

type Issue struct {
	Severity string
	Failure  string
	RuleName string
	Category string
	Position Position
	Confidence float64
}

type Position struct {
	Start Point
	End   Point
}

type Point struct {
	Filename string
	Offset   int
	Line     int
	Column   int
}

func main() {
	flag.Var(&excludes, "exclude", "list of globs which specify files to be excluded")
	flag.Usage = func() {
		fmt.Print(`
 _ __ _____   _(_)__  _____
| '__/ _ \ \ / / \ \ / / _ \
| | |  __/\ V /| |\ V /  __/
|_|  \___| \_/ |_| \_/ \___|

Example:
  revive -config c.toml -formatter friendly -exclude a.go -exclude b.go ./...

Usage of ./executable:
`)
		flag.PrintDefaults()
	}
	flag.Parse()

	if *versionFlag {
		fmt.Println("Version:\ta75b67b")
		fmt.Println("Commit:\t\ta75b67b73b9edb91dfc9f302dd108fa9d3ea5b05")
		fmt.Println("Built\t\t2026-04-17 19:59 UTC by build.sh")
		return
	}

	packages := flag.Args()
	if len(packages) == 0 {
		return
	}

	issues := []Issue{}
	fset := token.NewFileSet()

	for _, pkgPath := range packages {
		if pkgPath == "./..." {
			filepath.Walk(".", func(path string, info os.FileInfo, err error) error {
				if err != nil {
					return err
				}
				if !info.IsDir() && strings.HasSuffix(path, ".go") {
					issues = append(issues, lintFile(fset, path)...)
				}
				return nil
			})
		} else {
			info, err := os.Stat(pkgPath)
			if err != nil {
				continue
			}
			if info.IsDir() {
				filepath.Walk(pkgPath, func(path string, info os.FileInfo, err error) error {
					if err != nil {
						return err
					}
					if !info.IsDir() && strings.HasSuffix(path, ".go") {
						issues = append(issues, lintFile(fset, path)...)
					}
					return nil
				})
			} else {
				issues = append(issues, lintFile(fset, pkgPath)...)
			}
		}
	}

	if len(issues) > 0 {
		for _, issue := range issues {
			fmt.Printf("%s:%d:%d: %s\n", issue.Position.Start.Filename, issue.Position.Start.Line, issue.Position.Start.Column, issue.Failure)
		}
		if *setExitStatus {
			os.Exit(1)
		}
	}
}

func lintFile(fset *token.FileSet, path string) []Issue {
	issues := []Issue{}
	f, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
	if err != nil {
		return nil
	}

	// Rule: package-comments
	if f.Doc == nil {
		issues = append(issues, Issue{
			Severity: "warning",
			Failure:  "should have a package comment",
			RuleName: "package-comments",
			Category: "comments",
			Position: getPosition(fset, f.Package, f.Package), // Should be more precise
		})
	}

	// Rule: exported
	ast.Inspect(f, func(n ast.Node) bool {
		switch d := n.(type) {
		case *ast.FuncDecl:
			if d.Name.IsExported() && d.Doc == nil {
				issues = append(issues, Issue{
					Severity: "warning",
					Failure:  fmt.Sprintf("exported function %s should have comment or be unexported", d.Name.Name),
					RuleName: "exported",
					Category: "comments",
					Position: getPosition(fset, d.Pos(), d.Pos()),
				})
			}
		case *ast.GenDecl:
			if d.Tok == token.TYPE {
				for _, spec := range d.Specs {
					ts := spec.(*ast.TypeSpec)
					if ts.Name.IsExported() && d.Doc == nil {
						issues = append(issues, Issue{
							Severity: "warning",
							Failure:  fmt.Sprintf("exported type %s should have comment or be unexported", ts.Name.Name),
							RuleName: "exported",
							Category: "comments",
							Position: getPosition(fset, ts.Pos(), ts.Pos()),
						})
					}
				}
			}
		}
		return true
	})

	return issues
}

func getPosition(fset *token.FileSet, start, end token.Pos) Position {
	pStart := fset.Position(start)
	pEnd := fset.Position(end)
	return Position{
		Start: Point{
			Filename: pStart.Filename,
			Offset:   pStart.Offset,
			Line:     pStart.Line,
			Column:   pStart.Column,
		},
		End: Point{
			Filename: pEnd.Filename,
			Offset:   pEnd.Offset,
			Line:     pEnd.Line,
			Column:   pEnd.Column,
		},
	}
}
EOF
./compile.sh
./executable test.go"}

