		fmt.Print(" _ __ _____   _(_)__  _____\n| '__/ _ \\ \\ / / \\ \\ / / _ \\\n| | |  __/\\ V /| |\\ V /  __/\n|_|  \\___| \\_/ |_| \\_/ \\___|\n\nExample:\n  revive -config c.toml -formatter friendly -exclude a.go -exclude b.go ./...\n\nUsage of ./executable:\n")
