func getPosition(fset *token.FileSet, pos token.Pos) Position {
	p := fset.Position(pos)
	return Position{Start: Point{p.Filename, p.Offset, p.Line, p.Column}, End: Point{p.Filename, p.Offset, p.Line, p.Column}}
}

func formatIssues(issues []Issue) {
	switch *formatterName {
	case "json":
		b, _ := json.Marshal(issues)
		fmt.Println(string(b))
	case "ndjson":
		for _, i := range issues { b, _ := json.Marshal(i); fmt.Println(string(b)) }
	case "unix":
		for _, i := range issues { fmt.Printf("%s:%d:%d: [%s] %s\n", i.Position.Start.Filename, i.Position.Start.Line, i.Position.Start.Column, i.RuleName, i.Failure) }
