			if _, ok := files[i.Position.Start.Filename]; !ok { names = append(names, i.Position.Start.Filename) }
			files[i.Position.Start.Filename] = append(files[i.Position.Start.Filename], i)
		}
		sort.Strings(names); total := 0
		for _, name := range names {
			fmt.Println(name)
			for _, i := range files[name] {
				fmt.Printf("  (%d, %d)  https://revive.run/r#%-20s  %s\n", i.Position.Start.Line, i.Position.Start.Column, i.RuleName, i.Failure)
				total++
			}
			fmt.Println()
		}
		if total > 0 { fmt.Printf(" ✖ %d problems (0 errors) (%d warnings)\n", total, total) }
	case "checkstyle":
		fmt.Print("<?xml version='1.0' encoding='UTF-8'?>\n<checkstyle version=\"5.0\">\n")
		files := make(map[string][]Issue); var names []string
		for _, i := range issues {
			if _, ok := files[i.Position.Start.Filename]; !ok { names = append(names, i.Position.Start.Filename) }
			files[i.Position.Start.Filename] = append(files[i.Position.Start.Filename], i)
		}
		sort.Strings(names)
		for _, name := range names {
			fmt.Printf("    <file name=\"%s\">\n", name)
			for _, i := range files[name] {
				fmt.Printf("      <error line=\"%d\" column=\"%d\" message=\"%s (confidence %.0f)\" severity=\"%s\" source=\"revive/%s\"/>\n", i.Position.Start.Line, i.Position.Start.Column, i.Failure, i.Confidence, i.Severity, i.RuleName)
			}
			fmt.Printf("    </file>\n")
		}
		fmt.Print("</checkstyle>\n")
	case "friendly":
		total := 0; rules := make(map[string]int)
		for _, i := range issues {
			fmt.Printf("  ⚠  https://revive.run/r#%s  %s\n  %s:%d:%d\n\n", i.RuleName, i.Failure, i.Position.Start.Filename, i.Position.Start.Line, i.Position.Start.Column)
			total++; rules[i.RuleName]++
		}
		if total > 0 {
			fmt.Printf("⚠ %d problems (0 errors, %d warnings)\n\nWarnings:\n", total, total)
			var rnames []string
			for r := range rules { rnames = append(rnames, r) }
			sort.Strings(rnames)
			for _, r := range rnames { fmt.Printf("  %d  %s\n", rules[r], r) }
			fmt.Println()
		}
	case "sarif":
		// Simplified SARIF
		type Sarif struct {
			Version string `json:"version"`
			Runs    []Run  `json:"runs"`
		}
		type Run struct {
			Results []Result `json:"results"`
			Tool    Tool     `json:"tool"`
		}
		type Result struct {
			RuleID    string   `json:"ruleId"`
			Level     string   `json:"level"`
			Message   Message  `json:"message"`
			Locations []Location `json:"locations"`
		}
		type Message struct { Text string `json:"text"` }
		type Location struct { PhysicalLocation PhysicalLocation `json:"physicalLocation"` }
		type PhysicalLocation struct { ArtifactLocation ArtifactLocation `json:"artifactLocation"` ; Region Region `json:"region"` }
		type ArtifactLocation struct { URI string `json:"uri"` }
		type Region struct { StartLine int `json:"startLine"` ; StartColumn int `json:"startColumn"` }
		type Tool struct { Driver Driver `json:"driver"` }
		type Driver struct { Name string `json:"name"` ; InformationURI string `json:"informationUri"` ; Rules []SarifRule `json:"rules"` }
		type SarifRule struct { ID string `json:"id"` ; HelpURI string `json:"helpUri"` ; Properties RuleProps `json:"properties"` }
		type RuleProps struct { Severity string `json:"severity"` }

		s := Sarif{Version: "2.1.0", Runs: []Run{{Tool: Tool{Driver: Driver{Name: "revive", InformationURI: "https://revive.run", Rules: []SarifRule{{ID: "indent-error-flow", HelpURI: "https://revive.run/r#indent-error-flow", Properties: RuleProps{Severity: "warning"}}}}}}}}
		for _, i := range issues {
			s.Runs[0].Results = append(s.Runs[0].Results, Result{RuleID: i.RuleName, Level: i.Severity, Message: Message{Text: i.Failure}, Locations: []Location{{PhysicalLocation: PhysicalLocation{ArtifactLocation: ArtifactLocation{URI: i.Position.Start.Filename}, Region: Region{StartLine: i.Position.Start.Line, StartColumn: i.Position.Start.Column}}}}})
		}
		b, _ := json.MarshalIndent(s, "", "  ")
		fmt.Println(string(b))
	default:
		for _, i := range issues { fmt.Printf("%s:%d:%d: %s\n", i.Position.Start.Filename, i.Position.Start.Line, i.Position.Start.Column, i.Failure) }
	}
}
