func lintFile(fset *token.FileSet, path string, enabled map[string]bool) []Issue {
	issues := []Issue{}
	f, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
	if err != nil { return nil }
	fileDisabled := false
	disabledRules := make(map[string]bool)
	for _, cg := range f.Comments {
		for _, c := range cg.List {
			t := strings.TrimSpace(strings.TrimPrefix(c.Text, "//"))
			if t == "revive:disable" { fileDisabled = true }
			if strings.HasPrefix(t, "revive:disable:") { disabledRules[strings.TrimPrefix(t, "revive:disable:")] = true }
		}
	}
	if fileDisabled { return nil }

	if enabled["package-comments"] && !disabledRules["package-comments"] && f.Doc == nil {
		issues = append(issues, Issue{Severity:"warning", Failure:"should have a package comment", RuleName:"package-comments", Category:"comments", Position:getPosition(fset, f.Package), Confidence:1})
	}

	ast.Inspect(f, func(n ast.Node) bool {
		if n == nil { return true }
		switch d := n.(type) {
		case *ast.FuncDecl:
			if enabled["exported"] && !disabledRules["exported"] && d.Name.IsExported() && d.Doc == nil {
				issues = append(issues, Issue{Severity:"warning", Failure:fmt.Sprintf("exported function %s should have comment or be unexported", d.Name.Name), RuleName:"exported", Category:"comments", Position:getPosition(fset, d.Pos()), Confidence:1})
			}
		case *ast.GenDecl:
			if d.Tok == token.TYPE && enabled["exported"] && !disabledRules["exported"] {
				for _, spec := range d.Specs {
					ts := spec.(*ast.TypeSpec)
					if ts.Name.IsExported() && d.Doc == nil {
						issues = append(issues, Issue{Severity:"warning", Failure:fmt.Sprintf("exported type %s should have comment or be unexported", ts.Name.Name), RuleName:"exported", Category:"comments", Position:getPosition(fset, ts.Pos()), Confidence:1})
					}
				}
			}
			if d.Tok == token.IMPORT && (enabled["dot-imports"] || enabled["blank-imports"]) {
				for _, spec := range d.Specs {
					is := spec.(*ast.ImportSpec)
					if is.Name != nil && is.Name.Name == "." && enabled["dot-imports"] && !disabledRules["dot-imports"] {
						issues = append(issues, Issue{Severity:"warning", Failure:"should not use dot imports", RuleName:"dot-imports", Category:"style", Position:getPosition(fset, is.Pos()), Confidence:1})
					}
					if is.Name != nil && is.Name.Name == "_" && enabled["blank-imports"] && !disabledRules["blank-imports"] {
						issues = append(issues, Issue{Severity:"warning", Failure:"a blank import should be only in a main or test package, or have a comment justifying it", RuleName:"blank-imports", Category:"style", Position:getPosition(fset, is.Pos()), Confidence:1})
					}
				}
			}
		}
		return true
	})
	return issues
}

